#!/usr/bin/env python3
"""Generate the Active Satellites in Earth Orbit — 2026 Catalog Analysis HTML report."""

import csv
import json
import math
from collections import Counter, defaultdict
from datetime import datetime

CSV_PATH = "/app/benchmark/data.csv"
OUTPUT_PATH = "/app/output/final_report.html"

# ---------------------------------------------------------------------------
# 1. Load and parse data
# ---------------------------------------------------------------------------
rows = []
with open(CSV_PATH, newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

N = len(rows)

# Parse numeric fields
for r in rows:
    r["MEAN_MOTION"] = float(r["MEAN_MOTION"])
    r["INCLINATION"] = float(r["INCLINATION"])
    # ECCENTRICITY is a string like ".002524"
    r["ECCENTRICITY"] = float(r["ECCENTRICITY"])
    # Launch year from OBJECT_ID
    r["LAUNCH_YEAR"] = int(r["OBJECT_ID"][:4])

# ---------------------------------------------------------------------------
# 2. Compute KPIs
# ---------------------------------------------------------------------------
total_satellites = N

# LEO share (MEAN_MOTION > 14 rev/day)
leo_count = sum(1 for r in rows if r["MEAN_MOTION"] > 14)
leo_share_pct = round(leo_count / total_satellites * 100, 1)

# Starlink constellation size
starlink_count = sum(1 for r in rows if r["OBJECT_NAME"].upper().startswith("STARLINK"))

# Median inclination
inclinations = sorted(r["INCLINATION"] for r in rows)
n_incl = len(inclinations)
if n_incl % 2 == 0:
    median_inclination = (inclinations[n_incl // 2 - 1] + inclinations[n_incl // 2]) / 2
else:
    median_inclination = inclinations[n_incl // 2]
median_inclination = round(median_inclination, 1)

# Satellites launched since 2020
since_2020 = sum(1 for r in rows if r["LAUNCH_YEAR"] >= 2020)
since_2020_pct = round(since_2020 / total_satellites * 100, 1)

# EPOCH range
epochs = sorted(r["EPOCH"] for r in rows)
epoch_min = epochs[0][:10]  # just date part
epoch_max = epochs[-1][:10]

# ---------------------------------------------------------------------------
# 3. Orbital regime classification
# ---------------------------------------------------------------------------
# LEO:  MEAN_MOTION > 14
# MEO:  2 <= MEAN_MOTION <= 14
# GEO:  0.9 <= MEAN_MOTION <= 1.1 (geostationary band)
# HEO:  Everything else (highly elliptical / transitional)
leo = []
meo = []
geo = []
heo = []

for r in rows:
    mm = r["MEAN_MOTION"]
    if mm > 14:
        leo.append(r)
    elif 2 <= mm <= 14:
        meo.append(r)
    elif 0.9 <= mm <= 1.1:
        geo.append(r)
    else:
        heo.append(r)

regime_counts = {
    "LEO": len(leo),
    "MEO": len(meo),
    "GEO": len(geo),
    "HEO": len(heo),
}
regime_pcts = {k: round(v / N * 100, 1) for k, v in regime_counts.items()}

# ---------------------------------------------------------------------------
# 4. Constellation breakdown (by OBJECT_NAME prefix)
# ---------------------------------------------------------------------------
def get_constellation(name):
    """Extract constellation/operator prefix from OBJECT_NAME."""
    upper = name.upper().strip()
    # Known constellations
    if upper.startswith("STARLINK"):
        return "Starlink"
    if upper.startswith("ONEWEB"):
        return "OneWeb"
    if upper.startswith("IRIDIUM"):
        return "Iridium"
    if upper.startswith("GPS") or upper.startswith("NAVSTAR"):
        return "GPS"
    if upper.startswith("GLONASS") or upper.startswith("COSMOS") and "GLONASS" in upper:
        return "GLONASS"
    if upper.startswith("GALILEO"):
        return "Galileo"
    if upper.startswith("BEIDOU"):
        return "BeiDou"
    if upper.startswith("GLOBALSTAR"):
        return "Globalstar"
    if upper.startswith("ORBCOMM"):
        return "Orbcomm"
    if upper.startswith("YAOGAN"):
        return "Yaogan"
    if upper.startswith("FLOCK"):
        return "Flock (Planet Labs)"
    if upper.startswith("LEMUR"):
        return "Lemur (Spire)"
    if upper.startswith("SPACEBEE") or upper.startswith("SPACE BEE"):
        return "SpaceBee (Swarm)"
    if upper.startswith("ISS") or upper == "ISS":
        return "ISS"
    if upper.startswith("HST") or upper == "HST":
        return "Hubble"
    if upper.startswith("GOES"):
        return "GOES"
    if upper.startswith("SENTINEL"):
        return "Sentinel (Copernicus)"
    if upper.startswith("METEOSAT"):
        return "Meteosat"
    if upper.startswith("INTELSAT"):
        return "Intelsat"
    if upper.startswith("INMARSAT"):
        return "Inmarsat"
    if upper.startswith("TDRS"):
        return "TDRS"
    if upper.startswith("USA "):
        return "USA (Military)"
    if upper.startswith("COSMOS") or upper.startswith("COSMOS-"):
        return "Cosmos (Russia)"
    # Generic catch for satellites with identifiable prefixes
    # Look for first dash or space
    prefix = name.split("-")[0].strip()
    if prefix and len(prefix) > 2 and prefix.upper() != "OBJECT":
        return prefix
    return "Other"

constellation_counts = Counter()
for r in rows:
    constellation_counts[get_constellation(r["OBJECT_NAME"])] += 1

# Build constellation breakdown — top 15 + Other
top_constellations = constellation_counts.most_common(20)
