equatorial_pct = round(equatorial_count / N * 100, 1)

# Highly eccentric (ECC > 0.1)
high_ecc_count = sum(1 for r in rows if r["ECCENTRICITY"] > 0.1)

# Median eccentricity
ecc_sorted = sorted(ecc_vals)
median_ecc = ecc_sorted[len(ecc_sorted) // 2]

# Mean perigee height proxy: broader inclination stats
leo_mean_motion = [r["MEAN_MOTION"] for r in leo]
avg_leo_mean_motion = round(sum(leo_mean_motion) / len(leo_mean_motion), 2) if leo_mean_motion else 0

# Prep data for starlink launch trend
starlink_years = sorted(starlink_launch_years.keys())
starlink_trend = [(y, starlink_launch_years[y]) for y in starlink_years]

# Post-2015 for detailed view
launch_last10 = [(y, c) for y, c in launch_trend if y >= 2015]
cumulative_last10 = []
c = 0
for y, cnt in launch_last10:
